import os
import sys


def normalize(line):
    s = line.strip().lower()
    if s.count("@") != 1:
        return None
    local, domain = s.split("@")
    if not local or not domain:
        return None
    if "." not in domain or domain.startswith(".") or domain.endswith("."):
        return None
    if domain == "gmail.com":
        plus = local.find("+")
        if plus != -1:
            local = local[:plus]
        local = local.replace(".", "")
        if not local:
            return None
    return local + "@" + domain


def main():
    base = os.environ["INPUT"]
    path = os.path.join(base, "emails.txt")
    with open(path, "r", encoding="utf-8", errors="replace", newline="") as f:
        data = f.read()
    seen = set()
    invalid = 0
    for line in data.splitlines():
        if not line.strip():
            continue
        n = normalize(line)
        if n is None:
            invalid += 1
        else:
            seen.add(n)
    out = sys.stdout
    for addr in sorted(seen, key=lambda a: a.encode("utf-8", "surrogatepass")):
        out.write(addr + "\n")
    out.write("invalid %d\n" % invalid)


if __name__ == "__main__":
    main()

import os
import re

VALUES = [
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
    (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
    (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
]
SYM = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}


def to_roman(n):
    out = []
    for v, s in VALUES:
        while n >= v:
            out.append(s)
            n -= v
    return "".join(out)


def from_roman(s):
    total = 0
    for i, c in enumerate(s):
        v = SYM[c]
        if i + 1 < len(s) and SYM[s[i + 1]] > v:
            total -= v
        else:
            total += v
    return total


def convert(value):
    if re.fullmatch(r"[+-]?[0-9]+", value):
        n = int(value)
        if 1 <= n <= 3999:
            return to_roman(n)
        return "invalid"
    if re.fullmatch(r"[IVXLCDM]+", value):
        n = from_roman(value)
        if 1 <= n <= 3999 and to_roman(n) == value:
            return str(n)
        return "invalid"
    return "invalid"


def main():
    base = os.environ["INPUT"]
    path = os.path.join(base, "numbers.txt")
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        lines = f.read().splitlines()
    out = []
    for line in lines:
        value = line.strip()
        if not value:
            continue
        out.append(f"{value} = {convert(value)}")
    if out:
        print("\n".join(out))


if __name__ == "__main__":
    main()

import os
import sys


def check(line):
    pairs = {"(": ")", "[": "]", "{": "}"}
    closers = set(pairs.values())
    stack = []
    for i, ch in enumerate(line, 1):
        if ch in pairs:
            stack.append(pairs[ch])
        elif ch in closers:
            if not stack:
                return "col %d: unexpected %s" % (i, ch)
            exp = stack.pop()
            if exp != ch:
                return "col %d: expected %s, found %s" % (i, exp, ch)
    if stack:
        return "unclosed %s" % stack[-1]
    return "ok"


def main():
    d = os.environ["INPUT"]
    with open(os.path.join(d, "snippets.txt"), "r", encoding="ascii", errors="replace", newline="") as f:
        data = f.read()
    lines = data.split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    out = []
    for line in lines:
        if line.endswith("\r"):
            line = line[:-1]
        out.append(check(line))
    sys.stdout.write("".join(s + "\n" for s in out))


