    main()

import os
import sys
import heapq


def dijkstra(adj, src):
    best = {}
    heap = [(0, (src,))]
    while heap:
        cost, path = heapq.heappop(heap)
        node = path[-1]
        if node in best:
            continue
        best[node] = (cost, path)
        for nb, w in adj.get(node, {}).items():
            if nb not in best:
                heapq.heappush(heap, (cost + w, path + (nb,)))
    return best


def main():
    base = os.environ.get("INPUT", ".")
    with open(os.path.join(base, "routes.txt"), "rb") as f:
        data = f.read().decode("utf-8", "surrogateescape")
    adj = {}
    trips = []
    for raw in data.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        parts = line.split()
        if parts[0] == "road" and len(parts) >= 4:
            a, b = parts[1], parts[2]
            try:
                c = int(parts[3])
            except ValueError:
                continue
            adj.setdefault(a, {})
            adj.setdefault(b, {})
            if a == b:
                continue
            if b not in adj[a] or c < adj[a][b]:
                adj[a][b] = c
                adj[b][a] = c
        elif parts[0] == "trip" and len(parts) >= 3:
            trips.append((parts[1], parts[2]))
    cache = {}
    out = []
    for x, y in trips:
        if x == y:
            out.append("%s 0" % x)
            continue
        if x not in cache:
            cache[x] = dijkstra(adj, x)
        res = cache[x].get(y)
        if res is None:
            out.append("%s %s unreachable" % (x, y))
        else:
            cost, path = res
            out.append("%s %d" % (" -> ".join(path), cost))
    s = "\n".join(out)
    if out:
        s += "\n"
    sys.stdout.buffer.write(s.encode("utf-8", "surrogateescape"))


if __name__ == "__main__":
    main()

import json
import os
import sys


def merge(base, override):
    result = dict(base) if isinstance(base, dict) else {}
    for k, v in override.items():
        if v is None:
            result.pop(k, None)
        elif isinstance(v, dict):
            b = result.get(k)
            result[k] = merge(b if isinstance(b, dict) else {}, v)
        else:
            result[k] = v
    return result


def flatten(value, path, out):
    if isinstance(value, dict):
        if not value:
            out.append((path, "{}"))
            return
        for k, v in value.items():
            flatten(v, k if path is None else path + "." + k, out)
    elif isinstance(value, list):
        if not value:
            out.append((path, "[]"))
            return
        for i, v in enumerate(value):
            k = str(i)
            flatten(v, k if path is None else path + "." + k, out)
    else:
        out.append((path, json.dumps(value, ensure_ascii=False)))


def main():
    d = os.environ["INPUT"]
    with open(os.path.join(d, "base.json"), "r", encoding="utf-8") as f:
        base = json.load(f)
    with open(os.path.join(d, "override.json"), "r", encoding="utf-8") as f:
        override = json.load(f)
    if not isinstance(base, dict):
        base = {}
    if not isinstance(override, dict):
        override = {}
    merged = merge(base, override)
    out = []
    if merged:
        flatten(merged, None, out)
    out.sort(key=lambda p: (p[0] or "").encode("utf-8"))
    lines = "".join("%s=%s\n" % (p, v) for p, v in out)
    sys.stdout.buffer.write(lines.encode("utf-8"))
    sys.stdout.flush()


if __name__ == "__main__":
    main()

