def main():
    in_dir = os.environ["INPUT"]
    out_dir = os.environ["OUT"]
    path = os.path.join(in_dir, "app.log")

    buckets = {"error": [], "warn": [], "info": []}
    level_map = {"ERROR": "error", "WARN": "warn", "WARNING": "warn", "INFO": "info"}
    other = 0

    try:
        with open(path, "r", encoding="utf-8", errors="surrogateescape", newline="") as f:
            data = f.read()
    except FileNotFoundError:
        data = ""

    lines = data.split("\n")
