import os
import re
import sys

PART_RE = re.compile(r"part-\d{4}\.txt")
INT_RE = re.compile(r"[+-]?[0-9]+")


def read_part(path):
    """Return a list of ints, or None if the part is corrupt."""
    try:
        with open(path, "rb") as f:
            data = f.read()
    except OSError:
        return None
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        return None
    values = []
    for line in text.splitlines():
        s = line.strip()
        if not s:
            continue
        if not INT_RE.fullmatch(s):
            return None
        values.append(int(s))
    return values


def main():
    input_dir = os.environ["INPUT"]
    out_dir = os.environ["OUT"]

    names = []
    with os.scandir(input_dir) as it:
        for entry in it:
            if not PART_RE.fullmatch(entry.name):
                continue
            try:
                if not entry.is_file():
                    continue
            except OSError:
                continue
            names.append(entry.name)
    names.sort()

    parts = len(names)
    corrupt = 0
    merged = set()
    for name in names:
        vals = read_part(os.path.join(input_dir, name))
        if vals is None:
            corrupt += 1
            continue
        merged.update(vals)

    result = sorted(merged)
    out_path = os.path.join(out_dir, "merged.txt")
    tmp_path = out_path + ".tmp"
    with open(tmp_path, "w", encoding="utf-8", newline="\n") as f:
        for v in result:
            f.write(str(v))
            f.write("\n")
    os.replace(tmp_path, out_path)

    sys.stdout.write("parts %d corrupt %d values %d\n" % (parts, corrupt, len(result)))


if __name__ == "__main__":
    main()

import os
import shutil


def read_bytes(path):
    with open(path, "rb") as f:
        return f.read()


def main():
    src = os.environ["SRC"]
    dst = os.environ["DST"]

    src_names = sorted(
        (n for n in os.listdir(src) if os.path.isfile(os.path.join(src, n))),
        key=lambda s: os.fsencode(s),
    )
    dst_names = set(
        n for n in os.listdir(dst) if os.path.isfile(os.path.join(dst, n))
    )

    lines = []
    for name in src_names:
        sp = os.path.join(src, name)
        dp = os.path.join(dst, name)
        data = read_bytes(sp)
        if name not in dst_names:
            status = "added"
        elif read_bytes(dp) == data:
            status = "same"
        else:
            status = "updated"
        if status != "same":
            tmp = os.path.join(dst, ".sync-tmp-" + name)
            with open(tmp, "wb") as f:
                f.write(data)
            try:
                shutil.copymode(sp, tmp)
            except OSError:
                pass
            os.replace(tmp, dp)
        lines.append(f"{status} {name}")

    src_set = set(src_names)
    kept = sum(1 for n in dst_names if n not in src_set)
    lines.append(f"kept {kept}")
    print("\n".join(lines))


if __name__ == "__main__":
    main()

