import json
import os
import sys


def load(path):
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
        if isinstance(data, dict):
            return data
    except (FileNotFoundError, ValueError, OSError):
        pass
    return {}


def save(path, data):
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(data, f)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, path)


def main():
    input_dir = os.environ["INPUT"]
    kv_path = os.environ["USERS"]
    users = load(kv_path)

    with open(os.path.join(input_dir, "commands.txt"), "r", encoding="utf-8") as f:
        lines = f.read().splitlines()

    out = []
    changed = False
    for raw in lines:
        line = raw.strip()
        if not line:
            continue
        parts = line.split()
        cmd, args = parts[0], parts[1:]
        if cmd == "put" and len(args) == 3:
            uid, name, email = args
            users[uid] = {"name": name, "email": email}
            changed = True
            out.append(f"ok {uid}")
        elif cmd == "rename" and len(args) == 2:
            uid, name = args
            if uid in users:
                users[uid]["name"] = name
                changed = True
                out.append(f"ok {uid}")
            else:
                out.append(f"missing {uid}")
        elif cmd == "get" and len(args) == 1:
            uid = args[0]
            if uid in users:
                u = users[uid]
                out.append(json.dumps(
                    {"id": uid, "name": u["name"], "email": u["email"]},
                    separators=(",", ":"), ensure_ascii=False))
            else:
                out.append(f"missing {uid}")
        elif cmd == "del" and len(args) == 1:
            uid = args[0]
            if uid in users:
                del users[uid]
                changed = True
                out.append(f"ok {uid}")
            else:
                out.append(f"missing {uid}")
        elif cmd == "count" and len(args) == 0:
            out.append(f"count {len(users)}")
        else:
            out.append(f"bad {line}")

    if changed or not os.path.exists(kv_path):
        save(kv_path, users)

    if out:
        sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()

import json
import os
import sys
import tempfile


def load_state(path):
    if not path or not os.path.exists(path):
        return set(), {}
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
        ids = set(data.get("applied_ids", []))
        balances = {str(k): int(v) for k, v in data.get("balances", {}).items()}
        return ids, balances
    except Exception:
        sys.stderr.write("error: state file is corrupt\n")
        sys.exit(1)


def save_state(path, ids, balances):
    d = os.path.dirname(os.path.abspath(path)) or "."
    fd, tmp = tempfile.mkstemp(dir=d, prefix=".state-", suffix=".tmp")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            json.dump({"applied_ids": sorted(ids), "balances": balances}, f)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, path)
    except Exception:
        try:
            os.unlink(tmp)
        except OSError:
            pass
        raise


def parse_line(raw):
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        return None
    try:
        obj = json.loads(text)
    except (ValueError, RecursionError):
        return None
    if not isinstance(obj, dict):
        return None
    eid = obj.get("id")
    acct = obj.get("account")
    cents = obj.get("cents")
    if not isinstance(eid, str) or not isinstance(acct, str):
        return None
    if not isinstance(cents, int) or isinstance(cents, bool):
        return None
    return eid, acct, cents


def main():
    input_dir = os.environ.get("INPUT")
    state_path = os.environ.get("STATE")
    if not input_dir or not state_path:
        sys.stderr.write("error: INPUT and STATE must be set\n")
        sys.exit(1)

    ids, balances = load_state(state_path)

    events_path = os.path.join(input_dir, "events.jsonl")
    data = b""
    if os.path.exists(events_path):
        with open(events_path, "rb") as f:
            data = f.read()

    applied = duplicate = rejected = 0
    for raw in data.split(b"\n"):
        if raw.endswith(b"\r"):
            raw = raw[:-1]
        if raw.strip() == b"":
            continue
        ev = parse_line(raw)
        if ev is None:
            rejected += 1
            continue
        eid, acct, cents = ev
        if eid in ids:
            duplicate += 1
            continue
        ids.add(eid)
        balances[acct] = balances.get(acct, 0) + cents
        applied += 1

    save_state(state_path, ids, balances)

    out = ["applied %d duplicate %d rejected %d" % (applied, duplicate, rejected)]
    for acct in sorted(balances, key=lambda a: a.encode("utf-8", "surrogatepass")):
        out.append("%s %d" % (acct, balances[acct]))
    sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()

