def main():
    input_dir = os.environ["INPUT"]
    kv_path = os.environ["LIMITS"]

    state = load_state(kv_path)
    clients = state.get("clients")
    if not isinstance(clients, dict):
        clients = {}

    req_path = os.path.join(input_dir, "requests.txt")
