import os
import sys
import json


def load_board(path):
    try:
        with open(path, "r", encoding="utf-8", errors="surrogateescape") as f:
            data = json.load(f)
        if isinstance(data, dict):
            return data
    except (FileNotFoundError, ValueError, OSError):
        pass
    return {}


def save_board(path, data):
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8", errors="surrogateescape") as f:
        json.dump(data, f, ensure_ascii=True)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, path)


def main():
    input_dir = os.environ.get("INPUT", ".")
    board_path = os.environ.get("BOARD", "board.json")

    board = load_board(board_path)

    def add(name, pts):
        rec = board.get(name)
        if not isinstance(rec, list) or len(rec) != 2:
            rec = [0, 0]
        rec[0] += pts
        rec[1] += 1
        board[name] = rec

    games_path = os.path.join(input_dir, "games.txt")
    try:
        with open(games_path, "rb") as f:
            raw = f.read()
    except OSError:
        raw = b""

    text = raw.decode("utf-8", errors="surrogateescape")
    for line in text.splitlines():
        parts = line.split()
        if len(parts) == 2:
            w, l = parts
            add(w, 3)
            add(l, 0)
        elif len(parts) == 3 and parts[2] == "draw":
            w, l = parts[0], parts[1]
            add(w, 1)
            add(l, 1)

    save_board(board_path, board)

    def key(item):
        name, (pts, played) = item
        return (-pts, played, name.encode("utf-8", errors="surrogateescape"))

    ranked = sorted(board.items(), key=key)[:3]
    out = sys.stdout.buffer
    for i, (name, (pts, played)) in enumerate(ranked, 1):
        out.write(
            ("%d. " % i).encode()
            + name.encode("utf-8", errors="surrogateescape")
            + (" %d %d\n" % (pts, played)).encode()
        )
    out.flush()


if __name__ == "__main__":
    main()

