        with open(STORE, "r", encoding="utf-8") as f:
            data = json.load(f)
        if isinstance(data, dict) and "next" in data and "todos" in data:
            return data
    except Exception:
        pass
    return {"next": 1, "todos": {}}


def save(data):
    tmp = STORE + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(data, f)
        f.flush()
        try:
            os.fsync(f.fileno())
        except Exception:
            pass
    os.replace(tmp, STORE)


ID_RE = re.compile(r"^/todos/([1-9][0-9]*)$")
NOT_FOUND = (404, {"error": "not found"})


def parse_json(body):
    try:
        return json.loads(body.decode("utf-8"))
    except Exception:
        return None


def handle(method, target, body):
    parts = urlsplit(target)
    path = parts.path
    with LOCK:
        data = load()
        todos = data["todos"]
        if path == "/todos":
            if method == "GET":
                items = sorted(todos.values(), key=lambda t: t["id"])
                q = parse_qs(parts.query)
                if "done" in q:
                    v = q["done"][-1]
                    if v == "true":
                        items = [t for t in items if t["done"] is True]
                    elif v == "false":
                        items = [t for t in items if t["done"] is False]
                return 200, items
            if method == "POST":
                obj = parse_json(body)
                if not isinstance(obj, dict):
                    return 400, {"error": "title required"}
                title = obj.get("title")
                if not isinstance(title, str) or not title.strip():
                    return 400, {"error": "title required"}
                tid = data["next"]
                data["next"] = tid + 1
                todo = {"id": tid, "title": title.strip(), "done": False}
                todos[str(tid)] = todo
                save(data)
                return 201, todo
            return NOT_FOUND
        m = ID_RE.match(path)
        if not m:
            return NOT_FOUND
        key = str(int(m.group(1)))
        if method not in ("GET", "PATCH", "DELETE"):
            return NOT_FOUND
        todo = todos.get(key)
        if todo is None:
            return NOT_FOUND
        if method == "GET":
            return 200, todo
        if method == "DELETE":
            del todos[key]
            save(data)
            return 204, None
        # PATCH
        obj = parse_json(body)
        if not isinstance(obj, dict):
            return 400, {"error": "bad update"}
        new = dict(todo)
        if "title" in obj:
            t = obj["title"]
            if not isinstance(t, str) or not t.strip():
                return 400, {"error": "bad update"}
            new["title"] = t.strip()
        if "done" in obj:
            d = obj["done"]
            if not isinstance(d, bool):
                return 400, {"error": "bad update"}
            new["done"] = d
        todos[key] = new
        save(data)
        return 200, new


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *args):
        pass

    def _dispatch(self):
        length = 0
        try:
            length = int(self.headers.get("Content-Length") or 0)
        except ValueError:
            length = 0
        body = self.rfile.read(length) if length > 0 else b""
        try:
            status, payload = handle(self.command, self.path, body)
        except Exception:
            status, payload = 500, {"error": "internal"}
        self.send_response(status)
        if status == 204 or payload is None:
            self.send_header("Content-Length", "0")
            self.end_headers()
            return
        out = json.dumps(payload).encode("utf-8")
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(out)))
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(out)

    def __getattr__(self, name):
        if name.startswith("do_"):
            return self._dispatch
        raise AttributeError(name)


def main():
    port = int(os.environ.get("PORT", "8080"))
    server = ThreadingHTTPServer(("127.0.0.1", port), Handler)
    server.daemon_threads = True
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass


if __name__ == "__main__":
    main()

import json
import os
import re
import sqlite3
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlsplit, parse_qs

DB_PATH = os.environ["DB"]
PORT = int(os.environ.get("PORT", "8080"))

conn = sqlite3.connect(DB_PATH, check_same_thread=False)
conn.execute(
    "CREATE TABLE IF NOT EXISTS notes ("
    "id INTEGER PRIMARY KEY AUTOINCREMENT, "
    "title TEXT NOT NULL, body TEXT NOT NULL, tags TEXT NOT NULL)"
)
conn.commit()
lock = threading.Lock()

ID_RE = re.compile(r"^/notes/([0-9]+)$")


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):
        pass

    def send(self, code, obj):
        data = json.dumps(obj).encode("utf-8")
        self.send_response(code)
        self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def not_found(self):
        self.send(404, {"error": "not found"})

    def read_body(self):
        n = int(self.headers.get("content-length") or 0)
        return self.rfile.read(n) if n > 0 else b""

    def handle_any(self, method):
        try:
            raw = self.read_body()
            parts = urlsplit(self.path)
            path = parts.path
            if path == "/notes":
                if method == "POST":
                    return self.create(raw)
                if method == "GET":
                    return self.list(parts.query)
                return self.not_found()
            m = ID_RE.match(path)
            if m:
                nid = int(m.group(1))
                if method == "GET":
                    return self.get(nid)
                if method == "DELETE":
                    return self.delete(nid)
            return self.not_found()
        except Exception:
            try:
                self.not_found()
            except Exception:
                pass

    def create(self, raw):
        try:
            obj = json.loads(raw.decode("utf-8"))
        except Exception:
            return self.send(400, {"error": "invalid note"})
        if not isinstance(obj, dict):
            return self.send(400, {"error": "invalid note"})
        title = obj.get("title")
        body = obj.get("body")
        tags = obj.get("tags", [])
        if not isinstance(title, str) or title == "":
            return self.send(400, {"error": "invalid note"})
        if not isinstance(body, str):
            return self.send(400, {"error": "invalid note"})
        if not isinstance(tags, list) or not all(isinstance(t, str) for t in tags):
            return self.send(400, {"error": "invalid note"})
        seen = []
        for t in tags:
            lt = t.lower()
            if lt not in seen:
                seen.append(lt)
        with lock:
            cur = conn.execute(
                "INSERT INTO notes (title, body, tags) VALUES (?, ?, ?)",
                (title, body, json.dumps(seen)),
            )
            conn.commit()
            nid = cur.lastrowid
        self.send(201, {"id": nid})

    def get(self, nid):
        with lock:
            row = conn.execute(
                "SELECT id, title, body, tags FROM notes WHERE id = ?", (nid,)
            ).fetchone()
        if not row:
            return self.not_found()
        self.send(200, {"id": row[0], "title": row[1], "body": row[2],
                        "tags": json.loads(row[3])})

    def list(self, query):
        qs = parse_qs(query, keep_blank_values=True)
        tag = qs["tag"][0].lower() if "tag" in qs else None
        q = qs["q"][0] if "q" in qs else None
        with lock:
            rows = conn.execute(
                "SELECT id, title, body, tags FROM notes ORDER BY id DESC"
            ).fetchall()
        out = []
        for r in rows:
            if tag is not None and tag not in json.loads(r[3]):
                continue
            if q is not None and q not in r[1] and q not in r[2]:
                continue
            out.append({"id": r[0], "title": r[1]})
        self.send(200, out)

    def delete(self, nid):
        with lock:
            cur = conn.execute("DELETE FROM notes WHERE id = ?", (nid,))
            conn.commit()
            n = cur.rowcount
        if n == 0:
            return self.not_found()
        self.send(200, {"deleted": nid})

    def do_GET(self):
        self.handle_any("GET")

    def do_POST(self):
        self.handle_any("POST")

    def do_DELETE(self):
        self.handle_any("DELETE")

    def do_PUT(self):
        self.handle_any("PUT")

    def do_PATCH(self):
        self.handle_any("PATCH")

    def do_HEAD(self):
        self.handle_any("HEAD")

    def do_OPTIONS(self):
        self.handle_any("OPTIONS")


if __name__ == "__main__":
    srv = ThreadingHTTPServer(("127.0.0.1", PORT), Handler)
    srv.daemon_threads = True
    srv.serve_forever()
